import java.util.Properties
import com.android.build.api.dsl.ApplicationBuildType
import org.gradle.api.provider.ValueSource
import org.gradle.api.provider.ValueSourceParameters
import org.jetbrains.kotlin.gradle.dsl.JvmTarget
import org.jetbrains.kotlin.gradle.tasks.KotlinJvmCompile

/**
 * Gearslip: a phone-side Android Auto client built against the reverse-engineered AA wire
 * protocol, so a non-Google app can authenticate to and project onto a real car head unit
 * with no gearhead in the path. No third-party dependencies: the X.509 certificate is
 * generated by hand (see `SelfSignedCert`) so there is no BouncyCastle version to track and
 * no second crypto provider to collide with Conscrypt.
 */
plugins {
    alias(libs.plugins.android.application)
    alias(libs.plugins.kotlin.compose)
}

// The release signing key, read from an untracked keystore.properties beside this file or at the
// repository root. Third-party apps allowlist Gearslip by the SHA-256 of this certificate, so the
// key must stay the same for the life of the project - and must never be committed.
val keystoreProperties = Properties().apply {
    listOf(
        rootProject.file("keystore.properties"),
        project.file("keystore.properties"),
    ).firstOrNull { it.exists() }?.inputStream()?.use { load(it) }
}

// The human-readable version comes from the newest v* git tag, so a build can never disagree
// with its tag. A build of the tagged commit is named after it ("0.4.0-beta"); anything later
// adds the commits since and the commit ("0.4.0-beta+3.ba4374e"). The version *code* is a
// separate monotonic sequence described below; it never comes from a tag.
class GitVersion(val name: String, val code: Int)

// providers.exec is ValueSource-backed: Gradle records the command's output as a configuration
// input, re-runs it on later builds and invalidates the cache entry only when the value changes.
// So these git reads are safe with the configuration cache; the clock below is not, without help.
// Lazy so a build that pins -PgearslipVersionName (CI dev builds, local agent iteration) never
// runs git describe at all: every commit would otherwise invalidate the cached task graph.
val gitVersion: GitVersion by lazy {
    val described = runCatching {
        providers.exec {
            // Release tags generated by CI end in "-g<sha>"; ignore them so describe always
            // anchors on a hand-written version tag and the name below stays parseable.
            commandLine("git", "describe", "--tags", "--match", "v*", "--exclude", "*-g*", "--abbrev=7")
            isIgnoreExitValue = true
        }.standardOutput.asText.get().trim()
    }.getOrNull().orEmpty()
    val match = Regex("""^v((\d+)\.(\d+)\.(\d+)(?:-([A-Za-z]+))?)(?:-(\d+)-g([0-9a-f]+))?$""").find(described)
        ?: return@lazy GitVersion("0.0.0-dev", 1) // no git or no tags, e.g. a source download
    val (base, major, minor, patch, suffix, since, commit) = match.destructured
    val stage = when (suffix.lowercase()) {
        "" -> 9
        "beta" -> 2
        "alpha" -> 1
        else -> 0
    }
    GitVersion(
        name = if (since.isEmpty()) base else "$base+$since.$commit",
        code = ((major.toInt() * 100 + minor.toInt()) * 100 + patch.toInt()) * 10 + stage,
    )
}

// The update channel and the identity of this exact build. Stable and dev APKs share one
// package and one signing key (third-party car apps allowlist both), so their version codes
// must come from the same monotonic sequence or Android would refuse a channel switch. The
// sequence is minutes since the epoch by default; both publish workflows pass that exact value
// explicitly and record it with the release, so the app can also tell when an offered APK would
// be an out-of-order downgrade. Neither is a version number: [gitVersion] supplies the name.
val updateChannel = project.findProperty("gearslipChannel")?.toString()?.takeIf { it == "dev" } ?: "stable"
val buildSha = project.findProperty("gearslipBuildSha")?.toString()
    ?: runCatching {
        providers.exec {
            commandLine("git", "rev-parse", "--short=7", "HEAD")
            isIgnoreExitValue = true
        }.standardOutput.asText.get().trim()
    }.getOrNull().orEmpty()
// A bare System.currentTimeMillis() at configuration time is not a tracked input: with the
// configuration cache its value would be baked into a cached entry and reused by a later build,
// giving two different APKs the same version code. Reading the clock through a ValueSource makes
// it a configuration input, so Gradle re-reads it every build and invalidates the entry when it
// changes. Return minutes from obtain(), not milliseconds converted afterwards: Gradle tracks the
// ValueSource's own result, so dividing outside it would invalidate the entry on every build.
abstract class BuildClockValueSource : ValueSource<Long, ValueSourceParameters.None> {
    override fun obtain(): Long = System.currentTimeMillis() / 60_000L
}

val buildSequence = project.findProperty("gearslipBuildSeq")?.toString()?.toIntOrNull()
    ?: providers.of(BuildClockValueSource::class) { }.get().toInt()

// Keeps build output out of the module folder: <root>/build/gearslip/... instead of
// <root>/gearslip/build/..., so everything this project produces lands under one
// root-level build/ directory. Set before android {}, which works out the path to R8's default
// rules from it.
layout.buildDirectory.set(rootProject.layout.buildDirectory.dir("gearslip"))

android {
    namespace = "app.seb3thehacker.gearslip"
    compileSdk = 37

    defaultConfig {
        applicationId = "app.seb3thehacker.gearslip"
        minSdk = 31
        targetSdk = 37
        versionCode = buildSequence
        // -PgearslipVersionName=0.1.99-test makes a build that thinks it's older, to try the updater.
        versionName = project.findProperty("gearslipVersionName")?.toString() ?: gitVersion.name
        buildConfigField("String", "UPDATE_CHANNEL", "\"$updateChannel\"")
        buildConfigField("String", "BUILD_SHA", "\"$buildSha\"")
        manifestPlaceholders["appLabel"] = "Gearslip"
        // Where opted-in phones send their daily usage note: the stats-worker/ Worker's address,
        // set as gearslipStatsUrl in gradle.properties. Left empty, nothing is ever sent.
        buildConfigField("String", "STATS_URL", "\"${project.findProperty("gearslipStatsUrl") ?: ""}\"")
    }

    // Release and debug are shrunk identically so a debug install behaves like what ships (a
    // keep rule missing for release shows up in debug first). One definition instead of two
    // copies that can drift; -PnoR8 opts out for a quicker local build.
    val defaultProguardRules = getDefaultProguardFile("proguard-android-optimize.txt")
    fun ApplicationBuildType.shrinkWithR8() {
        isMinifyEnabled = true
        isShrinkResources = true
        proguardFiles(defaultProguardRules, "proguard-rules.pro")
    }

    signingConfigs {
        // Declared only when the properties file is present, so a clone without the key still
        // builds debug; assembleRelease then falls back to unsigned rather than failing here.
        if (keystoreProperties.getProperty("storeFile") != null) {
            create("release") {
                storeFile = rootProject.file(keystoreProperties.getProperty("storeFile"))
                storePassword = keystoreProperties.getProperty("storePassword")
                keyAlias = keystoreProperties.getProperty("keyAlias")
                keyPassword = keystoreProperties.getProperty("keyPassword")
            }
        }
    }

    buildTypes {
        release {
            signingConfig = signingConfigs.findByName("release")
            shrinkWithR8()
        }
        // Its own package, so a debug build installs beside the release one instead of over it.
        // Signed with the release key when it's here: both builds declare the car template
        // permission, and Android refuses a second app declaring it under a different key.
        debug {
            applicationIdSuffix = ".dev"
            signingConfigs.findByName("release")?.let { signingConfig = it }
            manifestPlaceholders["appLabel"] = "Gearslip Debug"
            // English (XA) and Arabic (XB) pseudo-locales show what's hardcoded and what doesn't
            // fit. They are a manual inspection aid, not something a published APK uses, so
            // generating them is opt-in: -PpseudoLocales for a layout-checking build.
            isPseudoLocalesEnabled = project.hasProperty("pseudoLocales")
            // Shrunk with R8 like a release; -PnoR8 skips it for a quicker build.
            if (!project.hasProperty("noR8")) shrinkWithR8()
        }
    }

    buildFeatures {
        buildConfig = true
    }

    // One small APK per ABI instead of a single 35 MB universal build. Most of the difference is
    // MapLibre's native libraries for ABIs a phone can't use. The updater picks the
    // asset matching Build.SUPPORTED_ABIS; the universal build stays as a fallback for anything
    // we didn't list. The DSL below is the public AGP API (verified against AGP 9.1.1).
    splits {
        abi {
            // -PgearslipAbi=arm64-v8a builds only that ABI, without the 35 MB universal fallback,
            // for quick local iteration. CI leaves this unset and still publishes every ABI plus
            // the universal APK the updater falls back to.
            val abis = project.findProperty("gearslipAbi")?.toString()
                ?.split(',')
                ?.map { it.trim() }
                ?.filter { it.isNotEmpty() }
                ?: listOf("arm64-v8a", "armeabi-v7a", "x86", "x86_64")
            isEnable = true
            reset()
            include(*abis.toTypedArray())
            isUniversalApk = abis.size > 1
        }
    }

    // Standalone Nothing car UI: English only, no per-app locale list to generate.
    androidResources { localeFilters += listOf("en") }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_21
        targetCompatibility = JavaVersion.VERSION_21
    }

    // MapLibre ships four ABIs; compressing them keeps the download small.
    packaging { jniLibs { useLegacyPackaging = true } }

    testOptions {
        // GearslipLog calls android.util.Log, which is a stub on the local JVM.
        unitTests.isReturnDefaultValues = true
    }

}

// Copies the produced APK to the root build/ folder (<root>/build/Gearslip-debug.apk) after the
// fact rather than fighting AGP's variant-output API across versions - simpler and doesn't break
// when that API moves again. A copy, not a move: AGP packages incrementally into the APK it left
// last time, and with that file gone a build came out holding nothing but classes.dex.
// Resolve paths during configuration: the task action then closes over plain Files instead of a
// Project, which the configuration cache cannot serialize.
val rootBuildDir = rootProject.layout.buildDirectory.get().asFile
val apkOutputDir = layout.buildDirectory.dir("outputs/apk").get().asFile

tasks.register("renameApk") {
    // Copy into task-local vals: referencing the script-level ones from doLast would capture the
    // script object itself, which the configuration cache refuses to serialize.
    val root = rootBuildDir
    val outputs = apkOutputDir
    doLast {
        // Drop copies from an earlier build, so a local run can't leave a now-unused ABI (or a
        // pre-split universal named Gearslip-debug.apk) in the set CI uploads.
        root.listFiles { file -> file.name.startsWith("Gearslip-") && file.extension == "apk" }
            ?.forEach { it.delete() }
        outputs.walkTopDown()
            .filter { it.extension == "apk" }
            .toList()
            .forEach { apk ->
                // AGP 9 puts every split next to the variant in outputs/apk/<variant>/ and names
                // them gearslip-<abi>-<variant>.apk, so the ABI comes from the file name. Without
                // splits the stem is just gearslip-<variant>, which keeps the old, flat name.
                val variant = apk.parentFile.name
                val abi = apk.nameWithoutExtension
                    .removePrefix("gearslip-")
                    .removeSuffix("-$variant")
                    .takeIf { it.isNotBlank() && it != variant }
                val name = if (abi == null) "Gearslip-$variant.apk" else "Gearslip-$abi-$variant.apk"
                apk.copyTo(File(root, name), overwrite = true)
            }
    }
}
tasks.matching { it.name.startsWith("assemble") }.configureEach { finalizedBy("renameApk") }

dependencies {
    // Music is driven entirely by external media apps (see media/CarMedia.kt): no first-party
    // streamer, so no ExoPlayer/catalog dependencies.

    // Only for the XML window theme (Theme.Material3.DynamicColors); every screen is Compose.
    implementation(libs.google.material)
    implementation(platform(libs.androidx.compose.bom))
    implementation(libs.androidx.compose.ui)
    implementation(libs.androidx.compose.material3)
    implementation(libs.androidx.compose.material.icons.core)
    implementation(libs.androidx.activity.compose)
    implementation(libs.androidx.lifecycle.runtime.compose)
    // Used from the host side, not the app side: Gearslip renders other apps' templates rather
    // than publishing its own, so this is here for the AIDL interfaces and the model classes
    // their Bundleables deserialize into.
    implementation(libs.androidx.car.app)
    implementation(libs.androidx.car.app.projected)
    implementation(libs.androidx.media)
    // The map behind a place list (PlaceListMapTemplate), which the host draws, not the app.
    implementation(libs.maplibre.android)
    // Keyless Google Directions traffic client (see traffic/VelaTrafficSource.kt).
    implementation(libs.okhttp)
    testImplementation(libs.junit)
    // The one androidTest only uses AndroidJUnit4 and assertions; Espresso is not referenced,
    // so pulling it into every build is dead weight. Keep runner: AndroidJUnit4 needs it.
    androidTestImplementation(libs.androidx.junit)
    androidTestImplementation("androidx.test:runner:1.6.2")
}

tasks.withType<KotlinJvmCompile>().configureEach {
    compilerOptions {
        jvmTarget.set(JvmTarget.JVM_21)
    }
}

